def city_card(n,title,tag):
    return f'<a class="city-card" href="{CITY}">{image(n,title)}<div><span class="eyebrow">{tag}</span><h3>{title} {ARROW}</h3></div></a>'

PHOTOS=[(25,'exterieur','La piscine et la façade de la villa'),(38,'exterieur','La piscine vue depuis la terrasse'),(40,'exterieur','La terrasse et le salon de jardin'),(123,'exterieur','La façade de la Villa Carissa'),(39,'exterieur','Le jardin et le golf de Samanah'),(29,'exterieur','Le jardin depuis l’étage'),(30,'salon','Le salon avec cheminée'),(33,'salon','Le salon et la salle à manger'),(32,'salon','La salle à manger'),(28,'chambre','La chambre master'),(37,'chambre','Une chambre donnant sur le jardin'),(34,'chambre','La chambre à deux lits'),(36,'chambre','La salle de bain avec baignoire'),(35,'chambre','La salle de bain avec douche'),(31,'chambre','La salle d’eau')]

