def golf():
    return page_hero(85,'LE GOLF DE SAMANAH','Le plaisir du jeu.<br><em>Le calme, autour.</em>','Votre séjour golfique à Marrakech, au cœur du domaine de Samanah.')+f'''<section class="intro section"><div class="intro-copy"><span class="eyebrow">UN PARCOURS SIGNÉ NICKLAUS</span><h2>Le golf,<br><em>à votre porte.</em></h2><p>La Villa Carissa se trouve dans le domaine sécurisé de Samanah. Depuis le jardin, la vue s’ouvre sur les espaces du golf et le pitch & putt.</p><p>Le parcours du Samanah Golf Club, ses greens et ses bunkers font partie du décor de vos vacances. À l’horizon, les montagnes de l’Atlas accompagnent la partie.</p>{link('/contact','Parlons de votre séjour golfique')}</div><div class="intro-visual">{image(82,'Le golf de Samanah dans la lumière du soir')}<span class="image-caption">LE GRAND AIR, DU MATIN AU SOIR.</span></div></section><section class="comfort section"><div><span class="eyebrow">VOTRE SÉJOUR SUR MESURE</span><h2>Une partie.<br><em>Puis la piscine.</em></h2></div><div><p>Retrouvez-vous à la villa après le parcours : quatre chambres, quatre salles de bain et des espaces communs pour partager la journée.</p><p>Pour les départs, cours et conditions d’accès au golf, contactez directement le club ou échangez avec nous avant votre arrivée.</p>{link('/contact','Organiser mon séjour')}</div></section><section class="section"><div class="section-heading"><div><span class="eyebrow">L’ESPRIT DES LIEUX</span><h2>Entre verts<br><em>et bleu du ciel.</em></h2></div></div><div class="editorial-grid">{image(80,'Les cactus et le parcours de Samanah')}{image(84,'Le club-house de Samanah')}{image(81,'Le panorama sur le golf et l’Atlas')}</div></section>'''

def city():
    places=[(104,'Le palais de la Bahia','Des patios, des zelliges et le détail des plafonds : prenez le temps de découvrir l’architecture marocaine.'),(108,'La Koutoubia','Son minaret dessine la silhouette de Marrakech. Une promenade dans les jardins pour la découvrir autrement.'),(105,'Les souks de la médina','Épices, étoffes, objets façonnés à la main. Flânez entre les étals et laissez-vous guider par les couleurs.'),(111,'Le jardin Majorelle','Le bleu, les cactus et les allées ombragées. Une parenthèse végétale au milieu de la ville.'),(113,'La vallée de l’Ourika','Quitter la ville pour les paysages du Haut Atlas, les villages et les cascades de la vallée.'),(112,'Une escapade à Essaouira','Les remparts, le port et l’air de l’Atlantique : changez d’horizon le temps d’une excursion.')]
    return page_hero(103,'LE CARNET DE MARRAKECH','Sortir. Flâner.<br><em>S’émerveiller.</em>','Nos envies de découvertes, entre médina, jardins et grand air.')+f'''<section class="page-intro"><span class="eyebrow">AU RYTHME DE LA VILLE ROUGE</span><h2>Il y a mille façons<br><em>de vivre Marrakech.</em></h2><p>Voici quelques idées à glisser entre deux journées au bord de la piscine.</p></section><section class="places section">{''.join(f'<article>{image(n,title)}<span class="eyebrow">0{i+1} / EXPLORER</span><h3>{title}</h3><p>{desc}</p></article>' for i,(n,title,desc) in enumerate(places))}</section><section class="intro section spa"><div class="intro-visual">{image(115,'Le patio des Bains de Marrakech')}</div><div class="intro-copy"><span class="eyebrow">UNE PAUSE POUR SOI</span><h2>Les Bains<br><em>de Marrakech.</em></h2><p>Un hammam, un soin, le calme d’un patio. Offrez-vous un moment de détente au cours de votre séjour.</p><p>Nous pouvons échanger sur vos envies et vous aider à préparer votre escapade.</p>{link('/contact','Préparer mes vacances')}</div></section>'''

def contact():
    return f'''<section class="page-intro contact-intro"><span class="eyebrow">VOTRE SÉJOUR COMMENCE ICI</span><h1>De belles vacances<br><em>commencent par un bonjour.</em></h1><p>Vos dates, vos envies, une question sur la maison ? Écrivez-nous.</p></section><section class="contact-layout section"><div class="contact-aside">{image(25,'La piscine de la Villa Carissa')}<h2>À votre écoute.</h2><a href="mailto:reservation@villacarissa-samanah.com">reservation@villacarissa-samanah.com</a><a href="tel:+212668214728">+212 668 214 728</a><p>Villa Carissa<br>Domaine de Samanah<br>Marrakech, Maroc</p>{link(AIRBNB,'Voir la villa sur Airbnb')}<p class="small-note">Tarifs et disponibilités à confirmer selon vos dates.</p></div><form id="contact-form"><span class="eyebrow">PARLONS DE VOTRE VOYAGE</span><div class="form-grid"><label>Votre prénom et nom<input name="nom" autocomplete="name" required placeholder="Comment vous appelez-vous ?"></label><label>Votre adresse email<input type="email" name="email" autocomplete="email" required placeholder="vous@exemple.fr"></label><label>Arrivée<input type="date" name="arrivee" required></label><label>Départ<input type="date" name="depart" required></label><label>Voyageurs<select name="voyageurs">{''.join(f'<option value="{i}">{i} personne'+('s' if i>1 else '')+'</option>' for i in range(1,9))}</select></label><label>Téléphone <span class="optional">(facultatif)</span><input name="telephone" type="tel" autocomplete="tel" placeholder="+33…"></label><label class="full">Un peu plus sur votre séjour<textarea name="message" rows="4" placeholder="Un séjour en famille, une escapade golfique, une envie particulière…"></textarea></label></div><p class="date-error" role="alert" hidden></p><button type="submit" class="button">Préparer mon email {ARROW}</button><p class="small-note">Votre messagerie s’ouvrira avec votre demande préremplie. Vous pourrez la relire avant de l’envoyer. Aucune réservation n’est confirmée par ce formulaire.</p><p id="contact-feedback" role="status" hidden>Votre email est prêt. Si votre messagerie ne s’ouvre pas, écrivez à <a href="mailto:reservation@villacarissa-samanah.com">reservation@villacarissa-samanah.com</a>.</p></form></section>'''

def legal():
    source=next(p for p in json.loads((ROOT/'source/legacy/pages.json').read_text()) if p['slug']=='mentions-legales')['content']['rendered']
    clean=re.sub(r'\[[^\]]*\]','',source)
    clean=re.sub(r'<p>\s*</p>','',clean)
    clean=re.sub(r'<(/?)h1\b',r'<\1h2',clean)
    clean=clean.replace('href="villacarissa-samanah.com"','href="http://villacarissa-samanah.com/"')
    return '<section class="page-intro"><span class="eyebrow">VILLA CARISSA</span><h1>Mentions <em>légales.</em></h1></section><article class="legal section"><p class="legal-notice">Les mentions ci-dessous sont conservées depuis le site d’origine, dans leur version du 30 juillet 2019. Les coordonnées de l’éditeur, l’hébergement et les informations relatives aux données personnelles devront être actualisés avant le remplacement du site actuel.</p>'+clean+'</article>'

def blog():
    return f'<section class="page-intro"><span class="eyebrow">LE CARNET CARISSA</span><h1>Blog & <em>actualités.</em></h1><p>Les prochaines nouvelles de la villa trouveront leur place ici.</p></section><section class="empty-state section"><h2>En attendant,<br><em>place aux découvertes.</em></h2><p>Aucun article n’était publié sur le site d’origine.</p>{link(CITY,"Explorer notre carnet de Marrakech")}</section>'

