pages=[('', 'home','Villa Carissa · Villa privée à Samanah, Marrakech','Une villa familiale à Marrakech, sur le golf de Samanah. 4 chambres, 4 salles de bain, 8 voyageurs et une piscine privée.',home),('toutes-les-photos','gallery','Toutes les photos · Villa Carissa','Découvrez les chambres, le salon, le jardin et la piscine privée de Villa Carissa à Marrakech.',gallery),('voyage-golfique-a-marrakech','golf','Le golf de Samanah · Villa Carissa','Préparez votre séjour golfique à Marrakech au cœur du domaine de Samanah.',golf),('location-de-villa-a-marrakech','city','Que faire à Marrakech · Villa Carissa','Souks, jardin Majorelle, palais de la Bahia, Ourika et Essaouira : notre carnet de Marrakech.',city),('contact','contact','Préparer votre séjour · Villa Carissa','Contactez Villa Carissa pour organiser votre séjour à Marrakech et connaître les disponibilités.',contact),('mentions-legales','legal','Mentions légales · Villa Carissa','Mentions légales historiques du site Villa Carissa.',legal),('category/uncategorized','blog','Blog & actualités · Villa Carissa','Le carnet et les actualités de la Villa Carissa à Marrakech.',blog)]
for slug,key,title,description,body in pages:
    folder=OUT/slug;folder.mkdir(parents=True,exist_ok=True)
    doc=f'''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{title}</title><meta name="description" content="{description}"><meta name="theme-color" content="#303c30"><meta property="og:title" content="{title}"><meta property="og:description" content="{description}"><meta property="og:type" content="website"><meta property="og:image" content="https://villa-carissa-samanah.fairloon33.chatgpt.site/assets/photo-25.webp"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="preload" href="/assets/font-1.ttf" as="font" type="font/ttf" crossorigin><link rel="stylesheet" href="/assets/fonts.css"><link rel="stylesheet" href="/assets/style.css"><script src="/assets/app.js" defer></script></head><body class="page-{key}">{header(key)}<main id="main">{body()}</main>{footer()}{dialogs()}</body></html>'''
    (folder/'index.html').write_text(doc)

# Old in-content links and the former home slug remain reachable.
for old,new in [('voyage-golfique-maroc',GOLF),('villa-carissa-a-samanah','/')]:
    p=OUT/old;p.mkdir(exist_ok=True);(p/'index.html').write_text(f'<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta http-equiv="refresh" content="0;url={new}"><title>Villa Carissa</title></head><body><a href="{new}">Continuer vers Villa Carissa</a></body></html>')
(OUT/'404.html').write_text('<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Page introuvable · Villa Carissa</title><link rel="stylesheet" href="/assets/fonts.css"><link rel="stylesheet" href="/assets/style.css"><main class="page-intro"><p class="eyebrow">VILLA CARISSA · 404</p><h1>Un petit <em>détour.</em></h1><p>Cette page est introuvable.</p><a class="button" href="/">Retour à la villa ↗</a></main></html>')
print(f'{len(pages)} pages built, 2 legacy aliases, 404')
